# PTX source for fp16 matrix‑vector multiplication (A[M,K] * B[K,1] = C[M,1])
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry matvec_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K
)
{
    // ------------------------------
    // registers
    // ------------------------------
    .reg .u64 %a_ptr, %b_ptr, %c_ptr;
    .reg .u32 %M, %K;
    .reg .u32 %tid, %bid, %bdim;
    .reg .u64 %row_idx, %row_offset;
    .reg .f32 %acc;
    .reg .u32 %i;
    .reg .pred %p_exit, %p_loop;
    .reg .u64 %i64, %addr_a, %addr_b, %tmp;
    .reg .f16 %a_h, %b_h, %c_h;
    .reg .f32 %a_f, %b_f;
    .reg .u64 %c_off, %c_addr;

    // ------------------------------
    // load kernel parameters
    // ------------------------------
    ld.param.u64 %a_ptr, [A_ptr];
    ld.param.u64 %b_ptr, [B_ptr];
    ld.param.u64 %c_ptr, [C_ptr];
    ld.param.u32 %M,     [M];
    ld.param.u32 %K,     [K];

    // ------------------------------
    // thread identification
    // ------------------------------
    mov.u32 %tid, %tid.x;          // threadIdx.x
    mov.u32 %bid, %ctaid.x;        // blockIdx.x
    mov.u32 %bdim, %ntid.x;        // blockDim.x

    // global row = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.u32 %tid, %bid, %bdim, %tid;   // %tid now holds global row index (u32)
    setp.ge.u32 %p_exit, %tid, %M;        // if row >= M exit
    @%p_exit bra DONE;

    // convert to 64‑bit for address arithmetic
    cvt.u64.u32 %row_idx, %tid;           // row index as u64

    // row_offset = row * K   (in element units)
    cvt.u64.u32 %tmp, %K;
    mul.lo.u64 %row_offset, %row_idx, %tmp;

    // ------------------------------
    // accumulation loop (fp32)
    // ------------------------------
    mov.f32 %acc, 0f00000000;            // acc = 0.0f
    mov.u32 %i, 0;

LOOP_START:
    setp.ge.u32 %p_loop, %i, %K;
    @%p_loop bra LOOP_END;

    // i (u64) for address calc
    cvt.u64.u32 %i64, %i;

    // ---- load A[row, i] -------------------------------------------------
    // address = A_ptr + ((row_offset + i) * sizeof(fp16))
    add.u64 %tmp, %row_offset, %i64;     // row_offset + i
    mul.lo.u64 %tmp, %tmp, 2;            // *2 bytes
    add.u64 %addr_a, %a_ptr, %tmp;
    ld.global.f16 %a_h, [%addr_a];

    // ---- load B[i, 0] ----------------------------------------------------
    // address = B_ptr + (i * sizeof(fp16))
    mul.lo.u64 %tmp, %i64, 2;
    add.u64 %addr_b, %b_ptr, %tmp;
    ld.global.f16 %b_h, [%addr_b];

    // ---- convert to fp32 -------------------------------------------------
    cvt.f32.f16 %a_f, %a_h;
    cvt.f32.f16 %b_f, %b_h;

    // ---- multiply‑accumulate ---------------------------------------------
    fma.rn.f32 %acc, %a_f, %b_f, %acc;

    // ++i
    add.u32 %i, %i, 1;
    bra LOOP_START;

LOOP_END:
    // ------------------------------
    // write result (fp16)
    // ------------------------------
    cvt.rn.f16.f32 %c_h, %acc;               // round to nearest fp16
    mul.lo.u64 %c_off, %row_idx, 2;          // C offset = row * sizeof(fp16)
    add.u64 %c_addr, %c_ptr, %c_off;
    st.global.f16 [%c_addr], %c_h;

DONE:
    ret;
}
'''

# ----------------------------------------------------------------------
# Python wrapper that loads the PTX and launches the kernel
# ----------------------------------------------------------------------
class ModelNew:
    def __init__(self):
        # Load PTX module using the provided harness
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        A : torch.Tensor of shape (M, K), dtype=torch.float16, device='cuda'
        B : torch.Tensor of shape (K, 1), dtype=torch.float16, device='cuda'
        Returns C : torch.Tensor of shape (M, 1), dtype=torch.float16, device='cuda'
        """
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        M, K = A.shape
        assert B.shape == (K, 1)

        # Allocate output
        C = torch.empty((M, 1), dtype=torch.float16, device='cuda')

        # Kernel launch configuration
        BLOCK_SIZE = 256
        grid_x = (M + BLOCK_SIZE - 1) // BLOCK_SIZE
        grid = (grid_x, 1, 1)
        block = (BLOCK_SIZE, 1, 1)

        # Prepare arguments: pointers are 64‑bit, dimensions are 32‑bit
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            int(M),   # uint32
            int(K)    # uint32
        ]

        # Launch the PTX kernel
        ptx_launch(self.module, "matvec_kernel", grid, block, args)

        return C
